(function(){
'use strict';
const KEY='nawaf-hq-v5';
const defaults={employees:[
{id:'sara',name:'سارة',role:'المدير العام AI',department:'الإدارة العامة',status:'READY',task:'',productivity:100},
{id:'omar',name:'عمر',role:'قائد التقنية والبحث',department:'التقنية والبحث',status:'READY',task:'',productivity:100},
{id:'lian',name:'ليان',role:'قائدة المنتج والتجربة',department:'المنتج والتجربة',status:'READY',task:'',productivity:100},
{id:'noura',name:'نورة',role:'قائدة الجودة والمراجعة',department:'الجودة والمراجعة',status:'READY',task:'',productivity:100}
],projects:[
{id:'mueen',name:'مُعِين',phase:'جاهز للعمل',progress:0,status:'ACTIVE'},
{id:'qaddha',name:'قدّها',phase:'جاهز للعمل',progress:0,status:'ACTIVE'},
{id:'nav',name:'ناڤ',phase:'جاهز للعمل',progress:0,status:'PAUSED'}
],tasks:[],approvals:[],reports:[],activity:[],settings:{motion:true,officeLabels:true,compact:false}};
let state=load(),view='dashboard',workspace='tasks',officeRoom=0;
const rooms=['الإدارة العامة','التقنية والبحث','المنتج والتجربة','الجودة والمراجعة','التحليلات','الأنظمة والبنية','البحث','العمليات'];
const statusMap={READY:'جاهز',IDLE:'متاح',WORKING:'يعمل',RESEARCHING:'يبحث',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظار نواف',COMPLETED:'مكتمل',PAUSED:'متوقف'};
function load(){try{return Object.assign(structuredClone(defaults),JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state));refreshStats()}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function addActivity(text,type='REAL'){state.activity.unshift({id:uid('a'),text,type,at:new Date().toISOString()});state.activity=state.activity.slice(0,100)}
function notify(t){const x=document.querySelector('.toast');if(!x)return;x.textContent=t;x.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>x.classList.remove('show'),1600)}
function boot(){document.getElementById('app').innerHTML=shell();bind();setView('dashboard');setTimeout(initOfficeUI,650);}
function shell(){return `<div class="hq"><aside class="side"><div><div class="brand">NAWAF <span>HQ</span><small>AI COMPANY OPERATING SYSTEM</small></div><div class="brand-copy" style="color:var(--muted);font-size:11px;margin-top:7px">واجهة تشغيل الشركة والموظفين والمشاريع</div></div><nav class="nav">${navBtn('dashboard','⌂','الرئيسية')}${navBtn('office','◈','المقر')}${navBtn('workforce','♙','الموظفون')}${navBtn('projects','▤','المشاريع')}${navBtn('tasks','✓','المهام')}${navBtn('approvals','◎','الموافقات')}${navBtn('reports','▧','التقارير')}${navBtn('settings','⚙','الإعدادات')}</nav><div class="side-status"><b>● SYSTEM READY</b>البيانات الحالية محفوظة محليًا في جهازك.<br>لا يتم اختلاق نشاط أو إنجازات.</div></aside><main class="main"><header class="top"><input class="search" id="global-search" placeholder="ابحث عن موظف، مشروع، مهمة أو تقرير..."><div class="ceo"><div class="avatar">N</div><span><b>نواف</b><small style="display:block;color:var(--muted)">CEO</small></span></div></header><section class="hero"><div><h1 id="page-title">لوحة القيادة</h1><p id="page-sub">كل شيء يبدأ من توجيهك ويظهر هنا بحالته الحقيقية.</p></div><div class="actions"><button class="soft" id="new-task">＋ مهمة</button><button class="soft" id="new-employee">＋ موظف</button><button class="primary" id="company-command">✦ توجيه الشركة</button></div></section><section class="stats" id="stats"></section><div id="content"></div></main></div><nav class="mobile-nav">${navBtn('dashboard','⌂','الرئيسية')}${navBtn('office','◈','المقر')}${navBtn('projects','▤','المشاريع')}${navBtn('tasks','✓','المهام')}${navBtn('settings','⚙','الإعدادات')}</nav><div class="modal" id="modal"><div class="dialog" id="dialog"></div></div><div class="toast"></div>`}
function navBtn(id,icon,label){return `<button type="button" data-view="${id}">${icon} <span>${label}</span></button>`}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.getElementById('new-task').onclick=()=>taskModal();document.getElementById('new-employee').onclick=()=>employeeModal();document.getElementById('company-command').onclick=commandModal;document.getElementById('global-search').oninput=e=>searchGlobal(e.target.value);document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')closeModal()}}
function refreshStats(){const busy=state.employees.filter(e=>!['READY','IDLE'].includes(e.status)).length;const done=state.tasks.filter(t=>t.status==='COMPLETED').length;const waiting=state.approvals.filter(a=>a.status==='WAITING').length;const avg=state.projects.length?Math.round(state.projects.reduce((n,p)=>n+(Number(p.progress)||0),0)/state.projects.length):0;const stats=document.getElementById('stats');if(stats)stats.innerHTML=`${stat(busy,'موظفون مشغولون')}${stat(state.tasks.length,'المهام')}${stat(done,'مكتمل')}${stat(waiting,'بانتظارك')}${stat(avg+'%','تقدم المشاريع')}`}
function stat(v,l){return `<div class="stat"><b>${esc(v)}</b><span>${l}</span></div>`}
function setView(v){view=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));const titles={dashboard:['لوحة القيادة','حالة الشركة الحقيقية الآن.'],office:['المقر التفاعلي','مكاتب الشركة والموظفون في مكان واحد.'],workforce:['القوى العاملة AI','إدارة الموظفين والحالات والتعليمات.'],projects:['المشاريع','كل مشروع ومرحلته وتقدمه.'],tasks:['المهام','إنشاء وإسناد وتتبع العمل.'],approvals:['موافقات CEO','الأشياء التي تحتاج قرارك فقط.'],reports:['التقارير','المخرجات الموثقة المحفوظة.'],settings:['الإعدادات','تحكم في واجهة وتشغيل Nawaf HQ.']};document.getElementById('page-title').textContent=titles[v][0];document.getElementById('page-sub').textContent=titles[v][1];refreshStats();const c=document.getElementById('content');if(v==='dashboard')c.innerHTML=dashboard();if(v==='office')c.innerHTML=officePage();if(v==='workforce')c.innerHTML=workforcePage();if(v==='projects')c.innerHTML=projectsPage();if(v==='tasks')c.innerHTML=tasksPage();if(v==='approvals')c.innerHTML=approvalsPage();if(v==='reports')c.innerHTML=reportsPage();if(v==='settings')c.innerHTML=settingsPage();bindContent();if(v==='dashboard'||v==='office')setTimeout(initOfficeUI,500)}
function commandCenter(){
 const active=state.tasks.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status));
 const ready=state.tasks.filter(t=>t.status==='READY');
 const done=state.tasks.filter(t=>t.status==='COMPLETED');
 const lead=active[0]||ready[0]||done[0];
 const leadEmp=lead?state.employees.find(e=>e.id===lead.employeeId):null;
 const result=lead?.aiResult?.summary||lead?.aiResult?.deliverable||'';
 return `<section class="command-center">
  <div class="command-top">
   <div><span class="eyebrow"><i></i> مركز العمليات مباشر</span><h2>كل العمل في مكان واحد</h2><p>راقب التنفيذ والنتائج لحظة بلحظة بدون تحديث الصفحة.</p></div>
   <div class="command-count"><b>${active.length}</b><span>يعمل الآن</span></div>
  </div>
  <div class="command-grid">
   <div class="mission-panel">
    <div class="panel-label">المهمة الحالية</div>
    ${lead?`<div class="mission-head"><div class="agent-orb">${esc((leadEmp?.name||'AI').slice(0,1))}</div><div><h3>${esc(lead.title)}</h3><p>${esc(leadEmp?.name||'موظف AI')} • ${esc(projectName(lead.projectId))}</p></div><span class="pill ${active.includes(lead)?'work':''}">${statusMap[lead.status]||lead.status}</span></div><div class="mission-progress"><span style="width:${lead.progress||0}%"></span></div><div class="mission-foot"><span>${lead.progress||0}%</span><span>${lead.status==='COMPLETED'?'تم حفظ النتيجة':active.includes(lead)?'التنفيذ جارٍ الآن':'جاهزة للبدء'}</span></div>${result?`<div class="live-result"><b>آخر نتيجة</b><p>${esc(String(result).slice(0,260))}</p><button class="ghost" data-task="${lead.id}">فتح النتيجة كاملة</button></div>`:''}`:'<div class="center-empty">لا توجد مهمة بعد. أرسل توجيهًا للشركة للبدء.</div>'}
   </div>
   <div class="pipeline-panel"><div class="panel-label">مسار العمل</div>
    <div class="pipeline-step"><b>${ready.length}</b><span>جاهزة</span></div>
    <div class="pipeline-step active"><b>${active.length}</b><span>قيد التنفيذ</span></div>
    <div class="pipeline-step done"><b>${done.length}</b><span>مكتملة</span></div>
   </div>
  </div>
  <div class="team-strip">${state.employees.slice(0,8).map(e=>`<button data-employee="${e.id}" class="team-chip"><span>${esc(e.name.slice(0,1))}</span><div><b>${esc(e.name)}</b><small>${statusMap[e.status]||e.status}</small></div><i class="${['WORKING','RESEARCHING','REVIEWING'].includes(e.status)?'busy':''}"></i></button>`).join('')}</div>
 </section>`}
function dashboard(){return `<div class="layout"><section class="operations-wrap card"><div class="office-head"><b>مركز تشغيل الشركة</b><span class="live"><i></i> LIVE</span></div>${commandCenter()}</section><aside class="stack"><section class="side-card card"><h3>الموظفون</h3><div class="list">${state.employees.slice(0,6).map(employeeRow).join('')||empty('لا يوجد موظفون')}</div></section><section class="side-card card"><h3>مشاريع نشطة</h3><div class="list">${state.projects.filter(p=>p.status==='ACTIVE').slice(0,5).map(projectRow).join('')||empty('لا توجد مشاريع نشطة')}</div></section><section class="side-card card"><h3>آخر النشاط</h3><div class="list">${state.activity.slice(0,5).map(a=>`<div class="row"><div><b>${esc(a.text)}</b><small>${new Date(a.at).toLocaleString('ar-SA')}</small></div></div>`).join('')||empty('لا يوجد نشاط بعد')}</div></section></aside></div><section class="workspace card">${workspaceBlock()}</section>`}
function officePage(){return `<section class="operations-wrap card"><div class="office-head"><b>NAWAF HQ • مركز العمليات</b><span class="live"><i></i> متصل</span></div>${commandCenter()}</section><section class="workspace card">${workspaceBlock()}</section>`}
function officeMarkup(){return commandCenter()}
function employeeRow(e){return `<button class="row" data-employee="${e.id}" style="width:100%;color:inherit;text-align:right;cursor:pointer"><div><b>${esc(e.name)}</b><small>${esc(e.role)}</small></div><span class="pill ${e.status==='WORKING'?'work':e.status==='WAITING_FOR_NAWAF'?'wait':''}">${statusMap[e.status]||e.status}</span></button>`}
function projectRow(p){return `<button class="row" data-project="${p.id}" style="width:100%;color:inherit;text-align:right;cursor:pointer"><div><b>${esc(p.name)}</b><small>${esc(p.phase)}</small></div><span class="pill">${Number(p.progress)||0}%</span></button>`}
function workspaceBlock(){return `<div class="workspace-head"><h2>مساحة العمل</h2><div class="tabs"><button class="${workspace==='tasks'?'active':''}" data-tab="tasks">المهام</button><button class="${workspace==='approvals'?'active':''}" data-tab="approvals">الموافقات</button><button class="${workspace==='reports'?'active':''}" data-tab="reports">التقارير</button></div></div>${workspace==='tasks'?taskList(state.tasks.slice(0,6)):workspace==='approvals'?approvalList(state.approvals.slice(0,6)):reportList(state.reports.slice(0,6))}`}
function workforcePage(){return `<section class="workspace card"><div class="workspace-head"><h2>الموظفون (${state.employees.length})</h2><button class="primary" data-add="employee">＋ إضافة موظف</button></div><div class="table">${state.employees.map(e=>`<div class="item"><div><b>${esc(e.name)}</b><div class="meta">${esc(e.role)} • ${esc(e.department)}</div></div><span class="pill ${e.status==='WORKING'?'work':''}">${statusMap[e.status]||e.status}</span><div class="meta">${esc(e.task||'بدون مهمة')}</div><div>${e.productivity||100}%</div><button class="ghost" data-employee="${e.id}">فتح</button></div>`).join('')||empty('لا يوجد موظفون')}</div></section>`}
function projectsPage(){return `<section class="workspace card"><div class="workspace-head"><h2>المشاريع (${state.projects.length})</h2><button class="primary" data-add="project">＋ مشروع</button></div><div class="table">${state.projects.map(p=>`<div class="item"><div><b>${esc(p.name)}</b><div class="meta">${esc(p.phase)}</div></div><span class="pill">${esc(p.status)}</span><div class="progress"><i style="width:${Math.max(0,Math.min(100,p.progress||0))}%"></i></div><div>${p.progress||0}%</div><button class="ghost" data-project="${p.id}">فتح</button></div>`).join('')||empty('لا توجد مشاريع')}</div></section>`}
function tasksPage(){return `<section class="workspace card"><div class="workspace-head"><h2>المهام (${state.tasks.length})</h2><button class="primary" data-add="task">＋ مهمة</button></div>${taskList(state.tasks)}</section>`}
function taskList(list){return `<div class="table task-table">${list.map(t=>{const summary=t.aiResult?.summary||t.aiResult?.deliverable||'';return `<div class="item task-item"><div class="task-main"><b>${esc(t.title)}</b><div class="meta">${esc(projectName(t.projectId))} • ${esc(employeeName(t.employeeId))}</div>${summary?`<div class="task-inline-result"><strong>النتيجة</strong><span>${esc(String(summary).slice(0,220))}</span></div>`:''}</div><span class="pill ${['WORKING','RESEARCHING','REVIEWING'].includes(t.status)?'work':t.status==='WAITING_FOR_NAWAF'?'wait':''}">${statusMap[t.status]||t.status}</span><div class="progress"><i style="width:${t.progress||0}%"></i></div><div class="task-percent">${t.progress||0}%</div><button class="ghost" data-task="${t.id}">${t.status==='COMPLETED'?'فتح النتيجة':'فتح'}</button></div>`}).join('')||empty('لا توجد مهام')}</div>`}
function approvalsPage(){return `<section class="workspace card"><div class="workspace-head"><h2>الموافقات (${state.approvals.filter(a=>a.status==='WAITING').length})</h2></div>${approvalList(state.approvals)}</section>`}
function approvalList(list){return `<div class="table">${list.map(a=>`<div class="item"><div><b>${esc(a.title)}</b><div class="meta">${esc(a.reason||'')}</div></div><span class="pill wait">${esc(a.status)}</span><div class="meta">${esc(projectName(a.projectId))}</div><div>${esc(a.cost||'$0')}</div><button class="ghost" data-approval="${a.id}">فتح</button></div>`).join('')||empty('لا توجد موافقات معلقة')}</div>`}
function reportsPage(){return `<section class="workspace card"><div class="workspace-head"><h2>التقارير (${state.reports.length})</h2><button class="primary" data-add="report">＋ تقرير</button></div>${reportList(state.reports)}</section>`}
function reportList(list){return `<div class="table">${list.map(r=>`<div class="item"><div><b>${esc(r.title)}</b><div class="meta">${esc(projectName(r.projectId))}</div></div><span class="pill">${esc(r.stage||'محفوظ')}</span><div class="meta">${esc(r.author||'')}</div><div>${new Date(r.createdAt).toLocaleDateString('ar-SA')}</div><button class="ghost" data-report="${r.id}">فتح</button></div>`).join('')||empty('لا توجد تقارير')}</div>`}
function settingsPage(){return `<section class="workspace card"><div class="workspace-head"><h2>الإعدادات</h2></div><div class="settings-grid"><div class="setting"><b>الحركة</b><p>تشغيل حركة المشهد والانتقالات.</p><label class="switch"><input type="checkbox" data-setting="motion" ${state.settings.motion?'checked':''}> تشغيل</label></div><div class="setting"><b>أسماء الأقسام</b><p>إظهار أزرار الأقسام فوق المقر.</p><label class="switch"><input type="checkbox" data-setting="officeLabels" ${state.settings.officeLabels?'checked':''}> إظهار</label></div><div class="setting"><b>تصدير البيانات</b><p>نسخة احتياطية بصيغة JSON.</p><button class="ghost" data-setting-action="export">تصدير</button></div><div class="setting"><b>إعادة ضبط الشركة</b><p>يرجع الموظفين الأساسيين والمشاريع بدون نشاط وهمي.</p><button class="ghost danger" data-setting-action="reset">إعادة ضبط</button></div></div></section>`}
function empty(t){return `<div class="empty">${t}</div>`}
function bindContent(){document.querySelectorAll('[data-employee]').forEach(x=>x.onclick=()=>employeeModal(x.dataset.employee));document.querySelectorAll('[data-project]').forEach(x=>x.onclick=()=>projectModal(x.dataset.project));document.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>taskModal(x.dataset.task));document.querySelectorAll('[data-approval]').forEach(x=>x.onclick=()=>approvalModal(x.dataset.approval));document.querySelectorAll('[data-report]').forEach(x=>x.onclick=()=>reportModal(x.dataset.report));document.querySelectorAll('[data-add]').forEach(x=>x.onclick=()=>({employee:employeeModal,project:projectModal,task:taskModal,report:reportModal}[x.dataset.add])());document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{workspace=x.dataset.tab;setView(view)});document.querySelectorAll('[data-setting]').forEach(x=>x.onchange=()=>{state.settings[x.dataset.setting]=x.checked;save();applySettings()});document.querySelectorAll('[data-setting-action]').forEach(x=>x.onclick=()=>x.dataset.settingAction==='reset'?resetAll():exportData())}
function initOfficeUI(){const host=document.querySelector('.office');if(!host)return;applySettings();host.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>focusRoom(Number(b.dataset.room)));host.querySelector('[data-office="overview"]')?.addEventListener('click',()=>focusRoom(-1));host.querySelector('[data-office="task"]')?.addEventListener('click',()=>taskModal());host.querySelector('[data-office="employee"]')?.addEventListener('click',()=>employeeModal());host.querySelector('[data-office="board"]')?.addEventListener('click',()=>{workspace='approvals';setView('dashboard');notify('تم فتح مساحة قرارات الشركة')});focusRoom(officeRoom)}
function focusRoom(i){officeRoom=i;const host=document.querySelector('.office');if(!host)return;host.querySelectorAll('[data-room]').forEach((b,n)=>b.classList.toggle('active',n===i));const t=host.querySelector('#office-title'),d=host.querySelector('#office-desc');if(i<0){t.textContent='مركز القيادة';d.textContent='النظرة العامة للمقر. اختر قسمًا أو افتح موظفًا من لوحة القوى العاملة.';return}const name=rooms[i];t.textContent=name;const team=state.employees.filter(e=>e.department===name);d.textContent=team.length?`عدد الموظفين في هذا القسم: ${team.length}. ${team.map(e=>e.name+' — '+(statusMap[e.status]||e.status)).join('، ')}`:'هذا القسم جاهز لإضافة موظفين أو مهام جديدة.'}
function employeeName(id){return state.employees.find(e=>e.id===id)?.name||'غير مسند'}function projectName(id){return state.projects.find(p=>p.id===id)?.name||'بدون مشروع'}
function openModal(html){document.getElementById('dialog').innerHTML=html;document.getElementById('modal').classList.add('open')}function closeModal(){document.getElementById('modal').classList.remove('open')}
function employeeModal(id){const e=state.employees.find(x=>x.id===id)||{id:'',name:'',role:'',department:'الإدارة العامة',status:'READY',task:'',productivity:100};openModal(`<h2>${id?'تعديل الموظف':'إضافة موظف AI'}</h2><form class="form" id="f"><label>الاسم<input name="name" value="${esc(e.name)}" required></label><label>الدور<input name="role" value="${esc(e.role)}" required></label><label>القسم<select name="department">${rooms.map(r=>`<option ${r===e.department?'selected':''}>${r}</option>`).join('')}</select></label><label>الحالة<select name="status">${Object.keys(statusMap).map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="full">المهمة الحالية<input name="task" value="${esc(e.task)}"></label><label>الإنتاجية<input name="productivity" type="number" min="0" max="100" value="${e.productivity||100}"></label><div class="full modal-actions"><button type="button" class="ghost" id="cancel">إغلاق</button>${id?'<button type="button" class="ghost danger" id="delete">حذف</button>':''}<button class="primary">حفظ</button></div></form>`);document.getElementById('cancel').onclick=closeModal;if(id)document.getElementById('delete').onclick=()=>{state.employees=state.employees.filter(x=>x.id!==id);addActivity('تم حذف موظف من القوى العاملة');save();closeModal();setView(view)};document.getElementById('f').onsubmit=ev=>{ev.preventDefault();const o=Object.fromEntries(new FormData(ev.target));o.productivity=Number(o.productivity)||0;if(id)Object.assign(e,o);else state.employees.push({...o,id:uid('e')});addActivity(`تم تحديث سجل الموظف ${o.name}`);save();closeModal();setView(view);notify('تم حفظ الموظف')}}
function projectModal(id){const p=state.projects.find(x=>x.id===id)||{name:'',phase:'جاهز للعمل',progress:0,status:'ACTIVE'};openModal(`<h2>${id?'تعديل المشروع':'مشروع جديد'}</h2><form class="form" id="f"><label>اسم المشروع<input name="name" value="${esc(p.name)}" required></label><label>الحالة<select name="status"><option ${p.status==='ACTIVE'?'selected':''}>ACTIVE</option><option ${p.status==='PAUSED'?'selected':''}>PAUSED</option><option ${p.status==='COMPLETED'?'selected':''}>COMPLETED</option></select></label><label class="full">المرحلة<input name="phase" value="${esc(p.phase)}"></label><label>التقدم %<input name="progress" type="number" min="0" max="100" value="${p.progress||0}"></label><div class="full modal-actions"><button type="button" class="ghost" id="cancel">إغلاق</button>${id?'<button type="button" class="ghost danger" id="delete">حذف</button>':''}<button class="primary">حفظ</button></div></form>`);document.getElementById('cancel').onclick=closeModal;if(id)document.getElementById('delete').onclick=()=>{state.projects=state.projects.filter(x=>x.id!==id);save();closeModal();setView(view)};document.getElementById('f').onsubmit=ev=>{ev.preventDefault();const o=Object.fromEntries(new FormData(ev.target));o.progress=Math.max(0,Math.min(100,Number(o.progress)||0));if(id)Object.assign(p,o);else state.projects.push({...o,id:uid('p')});addActivity(`تم تحديث مشروع ${o.name}`);save();closeModal();setView(view)}}
function taskModal(id){const t=state.tasks.find(x=>x.id===id)||{title:'',projectId:state.projects[0]?.id||'',employeeId:'',status:'READY',progress:0,details:''};openModal(`<h2>${id?'تعديل المهمة':'مهمة جديدة'}</h2><form class="form" id="f"><label class="full">عنوان المهمة<input name="title" value="${esc(t.title)}" required></label><label>المشروع<select name="projectId"><option value="">بدون مشروع</option>${state.projects.map(p=>`<option value="${p.id}" ${p.id===t.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>الموظف<select name="employeeId"><option value="">غير مسند</option>${state.employees.map(e=>`<option value="${e.id}" ${e.id===t.employeeId?'selected':''}>${esc(e.name)} — ${esc(e.role)}</option>`).join('')}</select></label><label>الحالة<select name="status">${['READY','WORKING','RESEARCHING','REVIEWING','WAITING_FOR_NAWAF','COMPLETED'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label><label>التقدم %<input name="progress" type="number" min="0" max="100" value="${t.progress||0}"></label><label class="full">التفاصيل<textarea name="details">${esc(t.details)}</textarea></label><div class="full modal-actions"><button type="button" class="ghost" id="cancel">إغلاق</button>${id?'<button type="button" class="ghost danger" id="delete">حذف</button>':''}<button class="primary">حفظ</button></div></form>`);document.getElementById('cancel').onclick=closeModal;if(id)document.getElementById('delete').onclick=()=>{state.tasks=state.tasks.filter(x=>x.id!==id);save();closeModal();setView(view)};document.getElementById('f').onsubmit=ev=>{ev.preventDefault();const o=Object.fromEntries(new FormData(ev.target));o.progress=Math.max(0,Math.min(100,Number(o.progress)||0));if(id)Object.assign(t,o);else state.tasks.push({...o,id:uid('t'),createdAt:new Date().toISOString()});if(o.employeeId){const e=state.employees.find(x=>x.id===o.employeeId);if(e){e.task=o.title;e.status=o.status==='COMPLETED'?'READY':o.status}}addActivity(`تم ${id?'تحديث':'إنشاء'} مهمة: ${o.title}`);save();closeModal();setView(view);notify('تم حفظ المهمة')}}
function approvalModal(id){const a=state.approvals.find(x=>x.id===id);if(!a)return;openModal(`<h2>${esc(a.title)}</h2><p style="color:var(--muted)">${esc(a.reason||'')}</p><div class="actions"><button class="primary" id="approve">اعتماد</button><button class="ghost danger" id="reject">رفض</button><button class="ghost" id="cancel">إغلاق</button></div>`);document.getElementById('approve').onclick=()=>decision('APPROVED');document.getElementById('reject').onclick=()=>decision('REJECTED');document.getElementById('cancel').onclick=closeModal;function decision(s){a.status=s;addActivity(`${s==='APPROVED'?'تم اعتماد':'تم رفض'}: ${a.title}`);save();closeModal();setView(view)}}
function reportModal(id){if(!id){openModal(`<h2>تقرير جديد</h2><form class="form" id="f"><label class="full">العنوان<input name="title" required></label><label>المشروع<select name="projectId"><option value="">بدون مشروع</option>${state.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>الكاتب<input name="author"></label><label class="full">المحتوى<textarea name="content" required></textarea></label><div class="full modal-actions"><button type="button" class="ghost" id="cancel">إغلاق</button><button class="primary">حفظ التقرير</button></div></form>`);document.getElementById('cancel').onclick=closeModal;document.getElementById('f').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));state.reports.unshift({...o,id:uid('r'),stage:'محفوظ',createdAt:new Date().toISOString()});addActivity(`تم حفظ تقرير: ${o.title}`);save();closeModal();setView(view)};return}const r=state.reports.find(x=>x.id===id);if(!r)return;openModal(`<h2>${esc(r.title)}</h2><p style="color:var(--muted)">${esc(r.author||'')} • ${esc(projectName(r.projectId))}</p><div style="white-space:pre-wrap;line-height:1.8">${esc(r.content||'')}</div><div class="modal-actions"><button class="ghost" id="cancel">إغلاق</button></div>`);document.getElementById('cancel').onclick=closeModal}
function commandModal(){openModal(`<h2>توجيه الشركة</h2><form class="form" id="f"><label class="full">وش تبغى الشركة تسوي؟<textarea name="command" placeholder="مثال: راجع مشروع مُعِين وحدد أهم المشاكل" required></textarea></label><label>المشروع<select name="projectId"><option value="">عام</option>${state.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>إسناد إلى<select name="employeeId"><option value="">سارة — المدير العام</option>${state.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><div class="full modal-actions"><button type="button" class="ghost" id="cancel">إغلاق</button><button class="primary">إنشاء المهمة</button></div></form>`);document.getElementById('cancel').onclick=closeModal;document.getElementById('f').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const employeeId=o.employeeId||state.employees.find(x=>x.id==='sara')?.id||'';state.tasks.unshift({id:uid('t'),title:o.command.slice(0,90),details:o.command,projectId:o.projectId,employeeId,status:'READY',progress:0,createdAt:new Date().toISOString()});const emp=state.employees.find(x=>x.id===employeeId);if(emp){emp.task=o.command.slice(0,90);emp.status='READY'}addActivity(`توجيه جديد من نواف: ${o.command.slice(0,70)}`);save();closeModal();setView('tasks');notify('تم تحويل التوجيه إلى مهمة جاهزة')}}
function searchGlobal(q){q=q.trim().toLowerCase();if(!q)return;if(state.employees.some(e=>(e.name+e.role+e.department).toLowerCase().includes(q))){setView('workforce');return}if(state.projects.some(p=>p.name.toLowerCase().includes(q))){setView('projects');return}if(state.tasks.some(t=>t.title.toLowerCase().includes(q))){setView('tasks');return}if(state.reports.some(r=>r.title.toLowerCase().includes(q)))setView('reports')}
function applySettings(){document.documentElement.classList.toggle('reduce-motion',!state.settings.motion);const rn=document.querySelector('.room-nav');if(rn)rn.style.display=state.settings.officeLabels?'grid':'none'}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nawaf-hq-backup.json';a.click();URL.revokeObjectURL(a.href);notify('تم تصدير نسخة احتياطية')}
function resetAll(){if(!confirm('متأكد؟ سيتم حذف المهام والتقارير والنشاط المحلي.'))return;state=structuredClone(defaults);save();setView('dashboard');notify('تمت إعادة ضبط الشركة')}
let liveRenderTimer;window.addEventListener('nawaf:state-updated',()=>{clearTimeout(liveRenderTimer);liveRenderTimer=setTimeout(()=>{state=load();refreshStats();if(!document.getElementById('modal')?.classList.contains('open'))setView(view)},60)});
async function cloudBoot(){try{if(window.HQCloudReady)await window.HQCloudReady}catch{}boot()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',cloudBoot);else cloudBoot();
})();